+			auto join_op =
+			    reinterpret_cast<LogicalJoin *>(op->children[i].get());
+			// push condition into join and remove from filter
+			join_op->SetJoinCondition(move(expr));
+			moved = true;
+		}
+	}
+
+	if (!moved) {
+		return move(expr);
+	} else {
+		return nullptr;
