+
+	bool Finished(timestamp_t current_value) {
+		if (greater_than_check) {
+			if (inclusive_bound) {
+				return current_value > end;
+			} else {
+				return current_value >= end;
+			}
+		} else {
+			if (inclusive_bound) {
+				return current_value < end;
+			} else {
+				return current_value <= end;
+			}
+		}
+	}
