+
+using namespace duckdb;
+using namespace std;
+
+TEST_CASE("Test Insertion Order Preserving Map: duplicate insert", "[api][.]") {
+	InsertionOrderPreservingMap<int> map;
+
+	map.insert("a", 1);
+	map.insert("b", 2);
+	map.insert("c", 3);
+	map.insert("b", 4);
+
+	auto it = map.find(string("c"));
+	map.erase(it);
+
+	int count = 0;
+	for (auto &x : map) {
+		count++;
+	}
+	REQUIRE(count == 2);
+}
+
+TEST_CASE("Test Insertion Order Preserving Map: double erase", "[api][.]") {
+	InsertionOrderPreservingMap<idx_t> map;
+	map.insert("a", 1);
+	map.insert("b", 2);
+	map.insert("c", 3);
+	map.insert("b", 4);
+	map.erase(map.find("c"));
+
+	int count = 0;
+	for (auto &x : map) {
+		count++;
+	}
+
+	REQUIRE(count == 2);
+
+	map.insert("a", 1);
+	map.insert("b", 2);
+	map.insert("c", 3);
+	map.insert("b", 4);
+	map.erase(map.find("c"));
+	map.erase(map.find("b"));
+
